import { printHelp } from "./ui.ts";
import { CDP, getBrowserWsUrl } from "./cdp.ts";
import { DEFAULT_PORT } from "./config.ts";

const DEFAULT_PAGE = "popup.html";

const HELP = `browser open-extension — open an extension page by name

Usage
  browser open-extension <name-pattern> [options]

Options
  --port <N>           CDP port (default: 9222)
  --page <page>        extension page (default: popup.html)

Environment
  EXTENSION_NAME       name pattern when no positional argument is given`;

function die(msg: string): never {
	console.error(`✗ ${msg}`);
	process.exit(1);
}

async function sleep(ms: number) {
	return await new Promise((resolve) => setTimeout(resolve, ms));
}

async function cdpFetch(port: number, path: string): Promise<unknown> {
	const response = await fetch(`http://127.0.0.1:${port}${path}`, {
		signal: AbortSignal.timeout(5000),
	});
	if (!response.ok) {
		throw new Error(`CDP ${path}: ${response.status}`);
	}
	return await response.json();
}

async function findExtensionId(
	port: number,
	namePattern: string,
): Promise<string | null> {
	const targets = (await cdpFetch(port, "/json/list")) as Array<{
		type: string;
		url?: string;
		webSocketDebuggerUrl?: string;
	}>;
	const serviceWorkers = targets.filter((t) => t.type === "service_worker");

	for (const sw of serviceWorkers) {
		const url = sw.url || "";
		const match = url.match(/^chrome-extension:\/\/([a-z]{32})\//);
		if (!match) continue;

		const extId = match[1];
		if (extId === "cimiefiiaegbelhefglklhhakcgmhkai") continue;

		try {
			const wsUrl = sw.webSocketDebuggerUrl;
			if (!wsUrl) continue;

			const cdp = await CDP.connect(wsUrl);
			const result = await cdp.send<{
				result?: { value?: string };
			}>("Runtime.evaluate", {
				expression: "chrome.runtime.getManifest().name",
				awaitPromise: true,
				returnByValue: true,
			});
			cdp.close();

			const extName = result?.result?.value;
			if (
				extName &&
				extName.toLowerCase().includes(namePattern.toLowerCase())
			) {
				return extId;
			}
		} catch {
			continue;
		}
	}

	return null;
}

async function waitForExtensionId(
	port: number,
	namePattern: string,
	timeoutMs = 15000,
): Promise<string | null> {
	const deadline = Date.now() + timeoutMs;

	while (Date.now() < deadline) {
