const DEV_SELECTOR_BUILDS = ["chrome-mv3", "chrome-mv3-dev"] as const;

/**
 * Newer of `.output/chrome-mv3` and `.output/chrome-mv3-dev` (manifest mtime).
 * A build with no manifest is skipped. If neither exists, still names
 * `.output/chrome-mv3` so the caller can report the missing one.
 */
export function resolveDevSelectorDir(root: string): string {
	let best: { dir: string; mtimeMs: number } | undefined;
	for (const name of DEV_SELECTOR_BUILDS) {
