 * (`--disable-extensions`), as before. `--keep-extensions` opts a
 * `--load-extension` run back into the profile's extensions too.
 *
 * `--dev-selector` adds that build on top. A windowed run that loads nothing
 * else does not isolate the profile; a run that already isolates (an explicit
 * extension, or headless) includes the selector in the allowed set.
 */
export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless" | "selectorDir">,
): string[] {
	const loaded = mergeExtensionDirs(options.loadExtension, options.selectorDir);
	const args: string[] = [];
	if (loaded) args.push(`--load-extension=${loaded}`);
	if (options.keepExtensions) return args;
	// Dev Selector alone must not strip a windowed profile's extensions.
	if (!options.loadExtension && !options.headless) return args;
	args.push(loaded ? `--disable-extensions-except=${loaded}` : "--disable-extensions");
	return args;
}

